        getSupportActionBar().hide();
        context = LocationDetails.this;
        searchableSpinner = new SearchableSpinner(context);
        castingViews();
        setListeners();
        cameraLauncher = registerForActivityResult(
                new ActivityResultContracts.TakePicture(),
                isSuccess -> {

                    if (!isSuccess || imageUri == null) {
                        return;
                    }
                    // IMPORTANT:
                    // Capture these before starting background thread
                    Uri capturedUri = imageUri;
                    File capturedCameraFile = cameraImageFile;

                    // IMPORTANT:
                    // Save which image was clicked BEFORE starting background thread
                    boolean isPhoto1 = photoClicked1;
                    boolean isPhoto2 = photoClicked2;
                    boolean isPhoto1Lt = photoClicked1_lt;

                    // Reset flags immediately
                    photoClicked1 = false;
                    photoClicked2 = false;
                    photoClicked1_lt = false;

                    if (is_image_1_clicked) {
                        loader_image.setVisibility(View.VISIBLE);
                        image_1.setVisibility(View.GONE);
                    }

                    if (is_image_2_clicked) {
                        loader_image_2.setVisibility(View.VISIBLE);
                        image_2.setVisibility(View.GONE);
                    }


                    if (is_image_1_lt_clicked) {
                        loader_image_lt_1.setVisibility(View.VISIBLE);
                        image_1_lt.setVisibility(View.GONE);
                    }


                    // Do image processing in background thread
                    executor.execute(() -> {

                        try {

                            Uri compressedUri;

                            // Compress image in background
                            compressedUri = CommanUtilits.compressImage(
                                    LocationDetails.this,
                                    imageUri
                            );

                            // DELETE ORIGINAL CAMERA IMAGE HERE
                            if (capturedCameraFile != null &&
                                    capturedCameraFile.exists()) {

                                capturedCameraFile.delete();
                            }

                            // Decode compressed image in background
                            Bitmap bitmap;

                            try (InputStream inputStream =
                                         getContentResolver()
                                                 .openInputStream(compressedUri)) {

                                bitmap = BitmapFactory.decodeStream(inputStream);
                            }

                            if (bitmap == null) {
                                throw new Exception("Bitmap decoding failed");
                            }

                            // Final UI update must happen on main thread
                            runOnUiThread(() -> {

                                if (isPhoto1) {

                                    compressedUriImage_1 = compressedUri;

                                    capturedBitmap1 = bitmap;

                                    image_1.setImageBitmap(bitmap);

                                    isImageCaptured1 = true;
                                    image_1_clicked = true;
                                    is_image_1_clicked = false;
                                    loader_image.setVisibility(View.GONE);
                                    image_1.setVisibility(View.VISIBLE);
                                } else if (isPhoto2) {

                                    compressedUriImage_2 = compressedUri;

                                    capturedBitmap2 = bitmap;

                                    image_2.setImageBitmap(bitmap);

                                    isImageCaptured2 = true;
                                    image_2_clicked = true;
                                    is_image_2_clicked = false;
                                    loader_image_2.setVisibility(View.GONE);
                                    image_2.setVisibility(View.VISIBLE);
                                } else if (isPhoto1Lt) {

                                    compressedUriImage_1_lt = compressedUri;

                                    capturedBitmap1_lt = bitmap;

                                    image_1_lt.setImageBitmap(bitmap);

                                    isImageCaptured1_lt = true;
                                    image_1_clicked_lt = true;

                                    loader_image_lt_1.setVisibility(View.GONE);
                                    image_1_lt.setVisibility(View.VISIBLE);
                                }


                            });

                        } catch (Exception e) {

                            e.printStackTrace();

                            runOnUiThread(() -> {

                                Toast.makeText(
                                        LocationDetails.this,
                                        "Unable to process image",
                                        Toast.LENGTH_SHORT
                                ).show();

                            });
                        }
                    });
                });

