        executor.execute(() -> {

            ArrayList<NewModel> editList =
                    databaseEstimates.getNewSurveyData(
                            EST_NO, "ALL", true, GIS_ID
                    );

            mainHandler.post(() -> {

                if (!isEdit) return;

                if (editList != null && !editList.isEmpty()) {

                    NewModel lastItem = editList.get(editList.size() - 1);

                    String lastSurveyType = lastItem.getVOLTAGE_LEVEL();
                    int poleNum = Integer.parseInt(lastItem.getPOLE_NO());
                    String surveyType = lastItem.getIS_EXISTING_LOCATION_NEW();
                    String poleFrom = lastItem.getFROM_POLE();
                    String lineType = lastItem.getLINE_TYPE();
                    String multiCircuit = lastItem.getIS_MULTI_CKT();

                    // LINE TYPE
                    posLineType = lineType.equalsIgnoreCase("OverHead") ? 0 : 1;
                    sp_lineType_11.setSelection(posLineType, true);

                    // MULTI CIRCUIT
                    posMultiCirCuit = multiCircuit.equalsIgnoreCase("No") ? 1 : 2;
                    sp_is_multi_circuit_11.setSelection(posMultiCirCuit, true);

                    // SURVEY TYPE
                    posSurveyType = surveyType.equalsIgnoreCase("Proposed") ? 0 : 1;
                    sp_is_location_exists.setSelection(posSurveyType, true);

                    // VOLTAGE LEVEL
                    if (lastSurveyType.equalsIgnoreCase("33KV")) {
                        pos = 1;
                    } else if (lastSurveyType.equalsIgnoreCase("11KV")) {
                        pos = 2;
                    } else {
                        pos = 3;
                    }
                    sp_voltage_level.setSelection(pos, true);

                    location_no.setText(String.valueOf(poleNum));

                    layout_parent_exists.setVisibility(View.GONE);
                    survey_33.setVisibility(View.VISIBLE);
                    survey_11.setVisibility(View.GONE);
                    survey_lt.setVisibility(View.GONE);

                    if (list33.isEmpty()) {
                        layout_connecting_point.setVisibility(View.GONE);
                    } else {

                        layout_connecting_point.setVisibility(View.VISIBLE);

                        if (!EstimatesMap.IS_INTERMEDIATE_POLE) {
                            layout_distance.setVisibility(View.VISIBLE);
                        } else {
                            layout_distance.setVisibility(View.GONE);
                        }

                        // Use Set to avoid duplicates
                        Set<String> poleSet = new HashSet<>();

                        // Collect all 33KV poles
                        for (NewModel model : list33) {
                            if (model.getPOLE_NO() != null && !model.getPOLE_NO().isEmpty()) {
                                poleSet.add(model.getPOLE_NO().trim()); // trim spaces
                            }
                        }

                        List<String> list_pst = new ArrayList<>(poleSet);

                        // 🔹 Filter poles by distance ≤ 120 meters
                        List<String> filteredPoles = new ArrayList<>();
                        for (String poleNo : list_pst) {
                            if (!poleNo.equals("0")) {
                                NewModel model = findModelByPoleNo(poleNo); // implement helper to get model
                                if (model != null) {
                                    double distance = getDistanceBetweenPoles33New(
                                            model.getLATITUDE() + "",
                                            model.getLONGITUDE() + "",
                                            Double.parseDouble(poleLat),
                                            Double.parseDouble(poleLon)
                                    );
                                    //System.out.println("DISTANCE_SOURCE_LOCATION" + distance);
                                    System.out.println("DISTANCE_VALIDATION_CHECK===>> 1" + distance + " " + isCrossingChecked);
                                    if (isCrossingChecked) {
                                        if (distance <= 500) {
                                            filteredPoles.add(poleNo.trim());
                                        }
                                    } else {
                                        if (distance <= 120) {
                                            filteredPoles.add(poleNo.trim());
                                        }
                                    }
                                }
                            } else {
                                filteredPoles.add("0"); // always keep 0
                            }
                        }

                        if (filteredPoles.isEmpty()) {
                            filteredPoles.addAll(list_pst);
                        }

                        Set<String> uniquePoles = new HashSet<>(filteredPoles);
                        filteredPoles.clear();
                        filteredPoles.addAll(uniquePoles);

                        // Sort numerically
                        Collections.sort(filteredPoles, new Comparator<String>() {
                            @Override
                            public int compare(String s1, String s2) {
                                try {
                                    return Integer.compare(
                                            Integer.parseInt(s2.trim()),
                                            Integer.parseInt(s1.trim())
                                    ); // swapped = descending
                                } catch (NumberFormatException e) {
                                    return s2.compareTo(s1); // fallback also descending
                                }
                            }
                        });


                        if (filteredPoles.contains("0")) {
                            filteredPoles.remove("0");

                        }
                        filteredPoles.add("0");

                        // 🔴 ALERT CONDITION
                        if (poleNumber > 2 && filteredPoles.size() == 1 && filteredPoles.get(0).equals("0")) {
                            if (list_pst.contains("0")) {
                                list_pst.remove("0");

                            }
                            list_pst.add("0");
                            ArrayAdapter<String> adapter_pst =
                                    new ArrayAdapter<>(
                                            context,
                                            android.R.layout.simple_dropdown_item_1line,
                                            filteredPoles
                                    );

                            sp_connecting_point.setAdapter(adapter_pst);

                        }
                        // Set adapter
                        ArrayAdapter<String> adapter_pst =
                                new ArrayAdapter<>(
                                        context,
                                        android.R.layout.simple_dropdown_item_1line,
                                        list_pst
                                );

                        sp_connecting_point.setAdapter(adapter_pst);
                        //sp_connecting_point.setSelection(0, true);
                    }


                }
            });
        });
