    private void validateData(boolean isChecked) {
        if (sp_voltage_level.getSelectedItem().toString().equalsIgnoreCase("33KV")) {
            layout_parent_exists.setVisibility(View.GONE);
            survey_33.setVisibility(View.VISIBLE);
            survey_11.setVisibility(View.GONE);
            survey_lt.setVisibility(View.GONE);
            layout_survey_pole_type.setVisibility(View.VISIBLE);
            // layout_sp_pole_height_33.setVisibility(View.VISIBLE);
            if (list33.isEmpty()) {
                layout_conductor_33.setVisibility(View.GONE);
            } else {
                layout_conductor_33.setVisibility(View.VISIBLE);
            }
            layout_distance.setVisibility(View.GONE);


            if (list33.isEmpty()) {
                layout_connecting_point.setVisibility(View.GONE);
            } else {
                layout_connecting_point.setVisibility(View.VISIBLE);

                if (!EstimatesMap.IS_INTERMEDIATE_POLE) {
                    layout_distance.setVisibility(View.VISIBLE);
                } else {
                    layout_distance.setVisibility(View.GONE);
                }

                List<String> list_pst = new ArrayList<>();

                // 🔹 Filter 33KV poles by distance ≤ 120 meters
                for (int i = 0; i < list33.size(); i++) {
                    String poleNo = list33.get(i).getPOLE_NO();
                    if (poleNo != null && !poleNo.trim().isEmpty() && !poleNo.equals("0")) {
                        double distance = getDistanceBetweenPoles33New(
                                list33.get(i).getLATITUDE() + "",
                                list33.get(i).getLONGITUDE() + "",
                                Double.parseDouble(poleLat),
                                Double.parseDouble(poleLon)
                        );
                        System.out.println("DISTANCE_SOURCE_LOCATION" + distance);
                        System.out.println("DISTANCE_VALIDATION_CHECK===>> TATA" + " DISTANCE " + distance + " " + isCrossingChecked + ":::" + isChecked);
                        if (isChecked) {
                            if (distance <= 500) {
                                list_pst.add(poleNo.trim());
                            }
                        } else {
                            if (distance <= 120) {
                                list_pst.add(poleNo.trim());
                            }
                        }
                    }
                }

                // 🔹 Fallback: if no poles within 120 meters, add all poles
                if (list_pst.isEmpty()) {
                    for (int i = 0; i < list33.size(); i++) {
                        String poleNo = list33.get(i).getPOLE_NO();
                        if (poleNo != null && !poleNo.trim().isEmpty()) {
                            list_pst.add(poleNo.trim());
                        }
                    }
                }

                // Add default "0" at top if missing
                if (list_pst.contains("0")) {
                    list_pst.remove("0");

                }

                // EDIT mode handling
                if (IS_EDIT) {
                    list_pst.remove(DATA_MODEL.getFROM_POLE());
                    list_pst.remove(DATA_MODEL.getPOLE_NO());
                    list_pst.add(DATA_MODEL.getFROM_POLE()); // add FROM_POLE at end
                }

                // 🔥 Remove duplicates
                Set<String> uniqueSet = new HashSet<>(list_pst);
                list_pst.clear();
                list_pst.addAll(uniqueSet);

                // 🔥 Sort numerically ascending
                Collections.sort(list_pst, new Comparator<String>() {
                    @Override
                    public int compare(String o1, String o2) {
                        try {
                            return Integer.parseInt(o2.trim()) - Integer.parseInt(o1.trim());
                        } catch (NumberFormatException e) {
                            return o2.compareTo(o1); // fallback
                        }
                    }
                });
                if (list_pst.isEmpty()) {
                    list_pst.add("Select");
                    list_pst.add("0");
                } else {
                    list_pst.add("0");
                }
                if (poleNumber > 2 && list_pst.size() == 1 && list_pst.get(0).equals("0")) {
                    list_pst.add("0");
                    ArrayAdapter<String> adapter_pst =
                            new ArrayAdapter<>(context, android.R.layout.simple_dropdown_item_1line, list_pst);

                    sp_connecting_point.setAdapter(adapter_pst);

                }
                // Set adapter
                ArrayAdapter<String> adapter_pst =
                        new ArrayAdapter<>(context, android.R.layout.simple_dropdown_item_1line, list_pst);

                sp_connecting_point.setAdapter(adapter_pst);
                //sp_connecting_point.setSelection(0, true);
            }

            layout_existing_connecting_point.setVisibility(View.GONE);

        } else if (sp_voltage_level.getSelectedItem().toString().equalsIgnoreCase("11KV")) {
            survey_33.setVisibility(View.GONE);
            survey_11.setVisibility(View.VISIBLE);
            survey_lt.setVisibility(View.GONE);
            layout_survey_pole_type.setVisibility(View.VISIBLE);
            //   layout_sp_pole_height_11.setVisibility(View.VISIBLE);
            if (list11.isEmpty()) {
                layout_conductor_11.setVisibility(View.GONE);
            } else {
                layout_conductor_11.setVisibility(View.VISIBLE);
            }
            layout_distance.setVisibility(View.GONE);


            if (list11.isEmpty()) {
                layout_parent_exists.setVisibility(View.VISIBLE);
                layout_connecting_point.setVisibility(View.GONE);
            } else {
                layout_parent_exists.setVisibility(View.GONE);
                layout_connecting_point.setVisibility(View.VISIBLE);

                if (!EstimatesMap.IS_INTERMEDIATE_POLE) {
                    layout_distance.setVisibility(View.VISIBLE);
                } else {
                    layout_distance.setVisibility(View.GONE);
                }

                List<String> list_pst = new ArrayList<>();

                // 🔹 Add poles within 120 meters
                for (int i = 0; i < list11.size(); i++) {
                    String poleNo = list11.get(i).getPOLE_NO();
                    if (poleNo != null && !poleNo.trim().isEmpty() && !poleNo.equals("0")) {
                        double distance = getDistanceBetweenPoles33New(
                                list11.get(i).getLATITUDE() + "",
                                list11.get(i).getLONGITUDE() + "",
                                Double.parseDouble(poleLat),
                                Double.parseDouble(poleLon)
                        );
                        System.out.println("DISTANCE_SOURCE_LOCATION" + distance);
                        if (isCrossingChecked) {
                            if (distance <= 500) {
                                list_pst.add(poleNo.trim());
                            }
                        } else {
                            if (distance <= 120) {
                                list_pst.add(poleNo.trim());
                            }
                        }
                    }
                }

                // 🔹 Fallback: if no poles within 120 meters, add all DTR poles
                if (list_pst.isEmpty()) {
                    for (int i = 0; i < list11.size(); i++) {
                        String poleNo = list11.get(i).getPOLE_NO();
                        if (poleNo != null && !poleNo.trim().isEmpty()) {
                            list_pst.add(poleNo.trim());
                        }
                    }
                }

                // Add default "0" at top
                if (list_pst.contains("0")) {
                    list_pst.remove("0");

                }

                // EDIT mode handling
                if (IS_EDIT) {
                    list_pst.remove(DATA_MODEL.getFROM_POLE());
                    list_pst.remove(DATA_MODEL.getPOLE_NO());
                    list_pst.add(DATA_MODEL.getFROM_POLE()); // add FROM_POLE at end
                }

                // 🔥 Remove duplicates
                Set<String> uniqueSet = new HashSet<>(list_pst);
                list_pst.clear();
                list_pst.addAll(uniqueSet);

                // 🔥 Sort numerically ascending
                Collections.sort(list_pst, new Comparator<String>() {
                    @Override
                    public int compare(String o1, String o2) {
                        try {
                            return Integer.parseInt(o2.trim()) - Integer.parseInt(o1.trim());
                        } catch (NumberFormatException e) {
                            return o2.compareTo(o1); // fallback for non-numeric
                        }
                    }
                });
                if (list_pst.isEmpty()) {
                    list_pst.add("Select");
                    list_pst.add("0");
                } else {
                    list_pst.add("0");
                }
                if (poleNumber > 2 && list_pst.size() == 1 && list_pst.get(0).equals("0")) {
                    list_pst.add("0");
                    ArrayAdapter<String> adapter_pst =
                            new ArrayAdapter<>(context, android.R.layout.simple_dropdown_item_1line, list_pst);

                    sp_connecting_point.setAdapter(adapter_pst);

                }
                ArrayAdapter<String> adapter_pst =
                        new ArrayAdapter<>(context, android.R.layout.simple_dropdown_item_1line, list_pst);

                sp_connecting_point.setAdapter(adapter_pst);
                //sp_connecting_point.setSelection(0, true);
            }


        } else if (sp_voltage_level.getSelectedItem().toString().equalsIgnoreCase("LT")) {


            survey_33.setVisibility(View.GONE);
            survey_11.setVisibility(View.GONE);
            survey_lt.setVisibility(View.VISIBLE);
            layout_survey_pole_type.setVisibility(View.VISIBLE);

            layout_parent_exists.setVisibility(View.GONE);
            //  layout_sp_pole_height_lt.setVisibility(View.VISIBLE);
            if (listLT.isEmpty()) {
                layout_conductor_lt.setVisibility(View.GONE);
            } else {
                layout_conductor_lt.setVisibility(View.VISIBLE);
            }
            layout_distance.setVisibility(View.GONE);

//03-01-2025 Chandu Changes
            if (listLT.isEmpty()) {
                if (!is33KVSelected && !is11KVSelected) {
                    if (isLTSelected) {
                        layout_parent_exists.setVisibility(View.GONE);
                        //  layout_connecting_point.setVisibility(View.GONE);
                    }
                } else {
                    layout_parent_exists.setVisibility(View.GONE);
                    // layout_connecting_point.setVisibility(View.GONE);

                }

            } else {
                layout_parent_exists.setVisibility(View.GONE);
                layout_distance.setVisibility(View.VISIBLE);

                List<String> list_pst = new ArrayList<>();

                // 🔹 Add DTR poles within 120 meters
                for (int i = 0; i < list11.size(); i++) {
                    if ("DTR Pole".equalsIgnoreCase(list11.get(i).getPOLE_CONFIG())) {
                        String poleNo = list11.get(i).getPOLE_NO();
                        if (poleNo != null && !poleNo.trim().isEmpty() && !poleNo.equals("0")) {
                            double distance = getDistanceBetweenPoles33New(
                                    list11.get(i).getLATITUDE() + "",
                                    list11.get(i).getLONGITUDE() + "",
                                    Double.parseDouble(poleLat),
                                    Double.parseDouble(poleLon)
                            );
                            System.out.println("DISTANCE_SOURCE_LOCATION" + distance);
                            if (isCrossingChecked) {
                                if (distance <= 500) {
                                    list_pst.add(poleNo.trim());
                                }
                            } else {
                                if (distance <= 120) {
                                    list_pst.add(poleNo.trim());
                                }
                            }
                        }
                    }
                }

                // 🔹 Add LT poles within 120 meters
                for (int i = 0; i < listLT.size(); i++) {
                    if (WorkInvolmentsActivity.SELECTED_LT_CKT
                            .equalsIgnoreCase(listLT.get(i).getLT_AVAILABLE())) {
                        String poleNo = listLT.get(i).getPOLE_NO();
                        if (poleNo != null && !poleNo.trim().isEmpty() && !poleNo.equals("0")) {
                            double distance = getDistanceBetweenPoles33New(
                                    listLT.get(i).getLATITUDE() + "",
                                    listLT.get(i).getLONGITUDE() + "",
                                    Double.parseDouble(poleLat),
                                    Double.parseDouble(poleLon)
                            );
                            System.out.println("DISTANCE_SOURCE_LOCATION" + distance);
                            if (isCrossingChecked) {
                                if (distance <= 500) {
                                    list_pst.add(poleNo.trim());
                                }
                            } else {
                                if (distance <= 120) {
                                    list_pst.add(poleNo.trim());
                                }
                            }
                        }
                    }
                }

                // 🔹 Fallback: if no poles within 120 meters, add all DTR + LT poles
                if (list_pst.isEmpty()) {
                    for (int i = 0; i < list11.size(); i++) {
                        if ("DTR Pole".equalsIgnoreCase(list11.get(i).getPOLE_CONFIG())) {
                            String poleNo = list11.get(i).getPOLE_NO();
                            if (poleNo != null && !poleNo.trim().isEmpty()) {
                                list_pst.add(poleNo.trim());
                            }
                        }
                    }
                    for (int i = 0; i < listLT.size(); i++) {
                        if (WorkInvolmentsActivity.SELECTED_LT_CKT
                                .equalsIgnoreCase(listLT.get(i).getLT_AVAILABLE())) {
                            String poleNo = listLT.get(i).getPOLE_NO();
                            if (poleNo != null && !poleNo.trim().isEmpty()) {
                                list_pst.add(poleNo.trim());
                            }
                        }
                    }
                }

                // Add default "0" at top if missing
                if (list_pst.contains("0")) {
                    list_pst.remove("0");

                }

                // EDIT mode handling
                if (IS_EDIT) {
                    list_pst.remove(DATA_MODEL.getFROM_POLE());
                    list_pst.remove(DATA_MODEL.getPOLE_NO());
                    list_pst.add(DATA_MODEL.getFROM_POLE()); // add FROM_POLE at end
                }

                // 🔥 Remove duplicates
                Set<String> uniqueSet = new HashSet<>(list_pst);
                list_pst.clear();
                list_pst.addAll(uniqueSet);

                // 🔥 Sort numerically ascending
                Collections.sort(list_pst, new Comparator<String>() {
                    @Override
                    public int compare(String o1, String o2) {
                        try {
                            return Integer.parseInt(o2.trim()) - Integer.parseInt(o1.trim());
                        } catch (NumberFormatException e) {
                            return o2.compareTo(o1); // fallback for non-numeric
                        }
                    }
                });
                if (list_pst.isEmpty()) {
                    list_pst.add("Select");
                    list_pst.add("0");
                } else {
                    list_pst.add("0");
                }

                if (poleNumber > 2 && list_pst.size() == 1 && list_pst.get(0).equals("0")) {
                    list_pst.add("0");
                    ArrayAdapter<String> adapter_pst =
                            new ArrayAdapter<>(context, android.R.layout.simple_dropdown_item_1line, list_pst);

                    sp_connecting_point.setAdapter(adapter_pst);

                }
                // Set adapter
                ArrayAdapter<String> adapter_pst =
                        new ArrayAdapter<>(context, android.R.layout.simple_dropdown_item_1line, list_pst);

                sp_connecting_point.setAdapter(adapter_pst);
                // sp_connecting_point.setSelection(0, true);
            }


        }
    }

