    private void restrictionForMultipleMappedProposedCase(String locationNo, String sourceLocation) {
        if (BTN_VALUE.equalsIgnoreCase("LT")) {
            // ✅ Check sourceLocation is not "0" and not equal to locationNo
            boolean isValidSource = sourceLocation.equalsIgnoreCase("0") || locationNo.equalsIgnoreCase(sourceLocation);

            //System.out.println("SELECTED_LOCATIONS " + locationNo + "Source" + sourceLocation);
            if (isValidSource) {
                androidx.appcompat.app.AlertDialog dialog = new androidx.appcompat.app.AlertDialog.Builder(this)
                        .setTitle("Duplicate Location")
                        .setMessage("The selected location already exists multiple times in LT or across 11KV/33KV/LT. Please verify.")
                        .setPositiveButton("OK", new DialogInterface.OnClickListener() {
                            @Override
                            public void onClick(DialogInterface dialog, int which) {
                                sp_exsting_connecting_point.setSelection(0, true);
                                sp_line_survey_type.setSelection(0, true);
                            }
                        })
                        .show();

                if (dialog.getWindow() != null) {
                    dialog.getWindow().setBackgroundDrawableResource(R.drawable.alert_dialog_bg);
                }
            }
        }
    }


    private void restrictionForMultipleTappingSameNo() {

        // Capture UI values first (UI thread safe)
        String btnValue = BTN_VALUE;
        String clickedFeeder = WorkInvolmentsActivity.CLICKED_FEEDER;
        String selectedLtCkt = WorkInvolmentsActivity.SELECTED_LT_CKT;
        String selectedPoleNo = EstimatesMap.selectedExiPoleNo;

        executor.execute(() -> {

            boolean shouldShowDialog = false;
            String dialogVoltage = null;

            if ("33KV".equalsIgnoreCase(btnValue) && IS_LINE_EXTENSION_33_DATA_AVAILABLE) {

                ArrayList<NewModel> list33 =
                        databaseEstimates.getNewSurveyData(
                                EST_NO, "33KV", false, GIS_ID
                        );

                String feederId = getFeederId33kv(clickedFeeder);

                if (list33 != null && feederId != null && selectedPoleNo != null) {
                    for (NewModel model : list33) {
                        if (model != null &&
                                feederId.equalsIgnoreCase(model.getFEEDER_ID()) &&
                                selectedPoleNo.equalsIgnoreCase(model.getEXT_LOCATION())) {

                            shouldShowDialog = true;
                            dialogVoltage = "33KV";
                            break;
                        }
                    }
                }

            } else if ("11KV".equalsIgnoreCase(btnValue) && IS_LINE_EXTENSION_11_DATA_AVAILABLE) {

                ArrayList<NewModel> list11 =
                        databaseEstimates.getNewSurveyData(
                                EST_NO, "11KV", false, GIS_ID
                        );

                String feederId = getFeederId(clickedFeeder);

                if (list11 != null && feederId != null && selectedPoleNo != null) {
                    for (NewModel model : list11) {
                        if (model != null &&
                                feederId.equalsIgnoreCase(model.getFEEDER_ID()) &&
                                selectedPoleNo.equalsIgnoreCase(model.getEXT_LOCATION())) {

                            shouldShowDialog = true;
                            dialogVoltage = "11KV";
                            break;
                        }
                    }
                }

            } else if ("LT".equalsIgnoreCase(btnValue)
                    && WorkInvolmentsActivity.IS_LT_EXISTING_SURVEY
                    && IS_LINE_EXTENSION_LT_DATA_AVAILABLE) {

                ArrayList<NewModel> listLT =
                        databaseEstimates.getNewSurveyData(
                                EST_NO, "LT", false, GIS_ID
                        );

                if (listLT != null && selectedLtCkt != null && selectedPoleNo != null) {
                    for (NewModel model : listLT) {
                        if (model != null &&
                                selectedLtCkt.equalsIgnoreCase(model.getLT_AVAILABLE()) &&
                                selectedPoleNo.equalsIgnoreCase(model.getEXT_LOCATION())) {

                            shouldShowDialog = true;
                            dialogVoltage = "LT";
                            break;
                        }
                    }
                }
            }

            boolean finalShow = shouldShowDialog;
            String finalVoltage = dialogVoltage;

            mainHandler.post(() -> {
                if (finalShow && finalVoltage != null) {
                    CustomDialog.showMultipleMappedMessageDialog(this, "Pay Attention!!",
                            "The existing pole/location number" + " " + selectedPoleNo + " " + " is already mapped", EST_NO, GIS_ID, 1, finalVoltage);
//                    openAlertDialogForMultipleTappingSameLoc(
//                            selectedPoleNo,
//                            finalVoltage
//                    );
                }
            });
        });
    }


    private void firstPoleValidation() {

        // Capture UI-thread values safely
        String btnValue = BTN_VALUE;
        String clickedFeeder = WorkInvolmentsActivity.CLICKED_FEEDER;

        executor.execute(() -> {

            boolean showAlert = false;

            if ("11KV".equalsIgnoreCase(btnValue)) {

                ArrayList<NewModel> list11KV =
                        databaseEstimates.getNewSurveyData(
                                EST_NO, "11KV", false, GIS_ID
                        );

                String feederId = getFeederId(clickedFeeder);
                if (feederId == null || list11KV == null) return;

                int locationCount = 0;

                for (NewModel model : list11KV) {

                    if (model == null || model.getFEEDER_ID() == null) continue;

                    if (feederId.equalsIgnoreCase(model.getFEEDER_ID())) {
                        locationCount++;
                    }

                    if (locationCount == 1
                            && "1".equalsIgnoreCase(model.getEXT_LOCATION())
                            && ("SS-BAY".equalsIgnoreCase(model.getPOLE_CONFIG())
                            || "SS BAY".equalsIgnoreCase(model.getPOLE_CONFIG()))) {

                        if (
                                ("FEEDER 1".equalsIgnoreCase(clickedFeeder) &&
                                        model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id1_11kv)) ||
                                        ("FEEDER 2".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id2_11kv)) ||
                                        ("FEEDER 3".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id3_11kv)) ||
                                        ("FEEDER 4".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id4_11kv)) ||
                                        ("FEEDER 5".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id5_11kv))
                        ) {
                            showAlert = true;
                            break;
                        }
                    }
                }

            } else if ("33KV".equalsIgnoreCase(btnValue)) {

                ArrayList<NewModel> list33KV =
                        databaseEstimates.getNewSurveyData(
                                EST_NO, "33KV", false, GIS_ID
                        );

                String feederId = getFeederId33kv(clickedFeeder);
                if (feederId == null || list33KV == null) return;

                int locationCount = 0;

                for (NewModel model : list33KV) {

                    if (model == null || model.getFEEDER_ID() == null) continue;

                    if (feederId.equalsIgnoreCase(model.getFEEDER_ID())) {
                        locationCount++;
                    }

                    if (locationCount == 1 &&
                            model.getEXT_LOCATION() != null &&
                            "1".equalsIgnoreCase(model.getEXT_LOCATION())) {

                        if (
                                ("FEEDER 1".equalsIgnoreCase(clickedFeeder) &&
                                        model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id1_33kv)) ||
                                        ("FEEDER 2".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id2_33kv)) ||
                                        ("FEEDER 3".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id3_33kv)) ||
                                        ("FEEDER 4".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id4_33kv)) ||
                                        ("FEEDER 5".equalsIgnoreCase(clickedFeeder) &&
                                                model.getFEEDER_ID().equalsIgnoreCase(WorkInvolmentsActivity.feeder_id5_33kv))
                        ) {
                            showAlert = true;
                            break;
                        }
                    }
                }
            }

            boolean finalShowAlert = showAlert;

            mainHandler.post(() -> {
                if (finalShowAlert) {
                    //openAlertDialogForFirstPole();
                    openAlertForSSBAYWarning("Mapping of Proposed pole by Tapping the SS Bay is not allowed?");

                }
            });
        });
    }


