    private void openAlertDialogForSSBAYLT(String poleConfig, String LINE_TYPE) {

        Dialog dialog = new Dialog(this);
        View view = getLayoutInflater().inflate(R.layout.customized_dialog, null);
        dialog.setContentView(view);

        // Views
        TextView title = view.findViewById(R.id.title);
        TextView message = view.findViewById(R.id.message);
        TextView okBtn = view.findViewById(R.id.okBtn);
        TextView cancelBtn = view.findViewById(R.id.cancelBtn);
        TextView tv_est_no = view.findViewById(R.id.tv_est_no);
        TextView tv_gis_id = view.findViewById(R.id.tv_gis_id);
        ImageView iv_icon = view.findViewById(R.id.iv_icon);

        tv_est_no.setText(getColoredText("Est No: ", EST_NO, context));
        tv_gis_id.setText(getColoredText("GIS ID: ", GIS_ID, context));

        // Set Title
        title.setText("Pay Attention!!");
        iv_icon.setImageDrawable(ContextCompat.getDrawable(context, R.drawable.warning));

        // Message Logic
        String msg = "";

        if (poleConfig != null && !poleConfig.isEmpty()) {

            if (poleConfig.equalsIgnoreCase("SS BAY") ||
                    poleConfig.equalsIgnoreCase("EHT SS-BAY") ||
                    poleConfig.equalsIgnoreCase("33/11KV SS-BAY")) {

                msg = "You cannot select the SS-Bay pole as a mapped pole";

            } else if (poleConfig.equalsIgnoreCase("RMU") ||
                    poleConfig.equalsIgnoreCase("UG Cable Route Marker") ||
                    "UNDERGROUND".equalsIgnoreCase(LINE_TYPE)) {

                msg = "You cannot connect the pole to ug route marker";
            }

        } else if (!"OVERHEAD".equalsIgnoreCase(LINE_TYPE)) {

            msg = "You cannot connect the pole to ug route marker";
        }

        message.setText(msg);

        // Button visibility
        okBtn.setVisibility(View.VISIBLE);
        cancelBtn.setVisibility(View.GONE);
        okBtn.setText("OK");

        // Click action
        okBtn.setOnClickListener(v -> {
            sp_exsting_connecting_point.setSelection(0, true);
            dialog.dismiss();
        });

        dialog.setCancelable(false);

        // Transparent background
        if (dialog.getWindow() != null) {
            dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);

            DisplayMetrics displayMetrics = getResources().getDisplayMetrics();
            int width = (int) (displayMetrics.widthPixels * 0.90);
            dialog.getWindow().setLayout(
                    width,
                    ViewGroup.LayoutParams.WRAP_CONTENT
            );
        }

        dialog.show();
    }

