    private void setNoOfLTCKT(String voltage_level) {
        List<String> count_lt_ckt = new ArrayList<>();
        count_lt_ckt.clear();
        count_lt_ckt.add("Select");

        int maxCount = 1; // default

        if (sp_lineType_11.getSelectedItem().toString().equalsIgnoreCase("OverHead")) {

            if (layout_dtr_phase_11kv.getVisibility() == View.VISIBLE) {
                String phase = sp_dtr_phase_11.getSelectedItem().toString();

                if (phase.equalsIgnoreCase("I")) {
                    maxCount = 1;

                } else if (phase.equalsIgnoreCase("III")) {
                    String capacity = sp_dtr_capacity_phase2_11.getSelectedItem().toString();

                    if (capacity.equalsIgnoreCase("160 KVA")
                            || capacity.equalsIgnoreCase("315 KVA")
                            || capacity.equalsIgnoreCase("500 KVA")) {
                        maxCount = 3;
                    } else {
                        maxCount = 2;
                    }
                }
            } else {
                if (tv_dtr_phase.getText().toString().equalsIgnoreCase("I")) {
                    maxCount = 1;
                } else if (tv_dtr_phase.getText().toString().equalsIgnoreCase("III")) {
                    String capacity = tv_dtr_capacity.getText().toString();

                    if (capacity.equalsIgnoreCase("160 KVA")
                            || capacity.equalsIgnoreCase("315 KVA")
                            || capacity.equalsIgnoreCase("500 KVA")) {
                        maxCount = 3;
                    } else {
                        maxCount = 2;
                    }
                }
            }


        } else {
            maxCount = 12;
        }

        for (int i = 1; i <= maxCount; i++) {
            switch (i) {
                case 1:
                    count_lt_ckt.add("1 (Single Feeding)");
                    break;
                case 2:
                    count_lt_ckt.add("2 (Double Feeding A & B)");
                    break;
                case 3:
                    count_lt_ckt.add("3 (Three Feedings A, B, C)");
                    break;
                default:
                    count_lt_ckt.add(String.valueOf(i));
                    break;
            }
        }
        ArrayAdapter<String> adapter = new ArrayAdapter<>(context, android.R.layout.simple_dropdown_item_1line, count_lt_ckt);
        sp_no_of_lt_circuits_11.setAdapter(adapter);
    }

    private double getDistanceBetweenPoles(double polLat, double polLon, double fromLat,
                                           double fromLon) {
        //System.out.println("CURRENT LOCATION LAT : " + fromLat);
        //System.out.println("CURRENT LOCATION LON : " + fromLon);
        //System.out.println("POLE LOCATION LAT : " + polLat);
        //System.out.println("POLE LOCATION LON : " + polLon);
        Location currentStartPoint = new Location("locationE");
        currentStartPoint.setLatitude(fromLon);
        currentStartPoint.setLongitude(fromLat);

        Location currentEndPoint = new Location("locationE");
        currentEndPoint.setLatitude(polLon);
        currentEndPoint.setLongitude(polLat);
        double currentDistance = currentStartPoint.distanceTo(currentEndPoint);
        //System.out.println("POLE LOCATION DISTANCE : " + currentDistance);
        return currentDistance;
    }


