    private void bindPole11KV(NewModel m) {

        String LINE_TYPE = safeString(m.getLINE_TYPE()).toUpperCase();
        String POLE_TYPE = safeString(m.getPOLE_TYPE()).toUpperCase();
        String POLE_HEIGHT = safeString(m.getPOLE_HEIGHT()).toUpperCase();
        String POLE_CONFIG = normalizePoleConfig11KV(m.getPOLE_CONFIG());
        String POLE_SUPPORT = safeString(m.getPOLE_SUPPORT()).toUpperCase();
        String PIN_CUT = safeString(m.getPIN_CUT()).toUpperCase();
        String POLE_CONCRETE = safeString(m.getPOLE_CONCRETE()).toUpperCase();
        String POLE_STRUCTURE = safeString(m.getPOLE_STRUCTURE()).toUpperCase();
        String CONDUCTOR_DESC = safeString(m.getCONDUCTOR_DESC()).toUpperCase();

        // LINE TYPE
        setSpinner(sp_lineType_11, LINE_TYPE.equals("OVERHEAD") ? 0 : 1);

        // SUPPORT
        setSpinner(sp_pole_support_11, "NONE".equals(POLE_SUPPORT) ? 1 : 0);

        // PIN / CUT
        setSpinner(sp_pole_pin_cut_point_11,
                PIN_CUT.equals("PINPOINT") ? 1 :
                        PIN_CUT.equals("CUTPOINT") ? 2 : 0);

        // CONCRETE
        setSpinner(sp_pole_concrete_11kv,
                POLE_CONCRETE.equals("YES") ? 2 :
                        POLE_CONCRETE.equals("NO") ? 1 : 0);

        // STRUCTURE
        setSpinner(sp_pole_structure_11kv,
                POLE_STRUCTURE.equals("SINGLE-POLE") ? 1 :
                        POLE_STRUCTURE.equals("DOUBLE-POLE") ? 2 :
                                POLE_STRUCTURE.equals("FOUR-POLE") ? 3 : 0);

        // POLE TYPE
        setupPoleTypeSpinner11KV(POLE_TYPE, POLE_HEIGHT);

        // HEIGHT
        //setupHeightSpinner11KV(POLE_TYPE, POLE_HEIGHT);

        // CONFIG
        setupPoleConfigSpinner11KV(LINE_TYPE, POLE_CONFIG);

        // CONDUCTOR
        setupConductorSpinner11KV(LINE_TYPE, CONDUCTOR_DESC);
    }

    private void setupPoleTypeSpinner11KV(String poleType, String poleHeight) {

        List<String> list = getPoleTypeList();

        SpinnerAdapter<String> adapter11KV = new SpinnerAdapter<>(context, list);
        // STEP 1: remove listener and set adapter
        sp_pole_type_11.setOnItemSelectedListener(null);
        sp_pole_type_11.setAdapter(adapter11KV);

        // STEP 2: restore selection (repeatPole)
        if (poleType != null && !poleType.isEmpty()) {
            int pos = list.indexOf(poleType);
            if (pos >= 0) {
                sp_pole_type_11.post(() -> {

                    // restore pole type
                    sp_pole_type_11.setSelection(pos, false);

                    // restore height AFTER pole type
                    setupHeightSpinner11KV(poleType, poleHeight);

                    // STEP 3: attach listener ONLY AFTER restore
                    attachPoleTypeListener11KV(list);
                });
                return;
            }
        }

        // Normal (no repeatPole)
        attachPoleTypeListener11KV(list);
    }

    private void attachPoleTypeListener11KV(List<String> list) {

        sp_pole_type_11.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> parent, View view, int position, long id) {

                if (position < 0 || position >= list.size()) return;

                String selectedPoleType = list.get(position);

                // USER change → rebuild height
                setupHeightSpinner11KV(selectedPoleType, null);
            }

            @Override
            public void onNothingSelected(AdapterView<?> parent) {
            }
        });
    }

    private void setupHeightSpinner11KV(String poleType, String poleHeight) {
        String pole_type = poleType;

        List<String> heightList = new ArrayList<>();
        heightList.add("Select");

        if (poleType == null) poleType = "";

        switch (poleType) {
            case "PSCC":
                heightList.addAll(Arrays.asList("8", "9.1", "11"));
                break;
            case "SPUN":
                heightList.addAll(Arrays.asList("9.5", "11", "12.5"));
                break;
            case "TOWER":
                heightList.addAll(Arrays.asList("M+3", "M+6", "M+9", "M+12", "R+"));
                break;
            case "RS JOIST":
            case "TUBULAR POLE":
                heightList.addAll(Arrays.asList("9.1", "11"));
                break;
            case "RAIL":
                heightList.addAll(Arrays.asList("9.5", "11", "12.5"));
                break;
        }

        SpinnerAdapter<String> adapter11KV = new SpinnerAdapter<String>(context, heightList);
        sp_pole_height_11.setOnItemSelectedListener(null);
        sp_pole_height_11.setAdapter(adapter11KV);

        if (poleHeight != null && !poleHeight.isEmpty()) {
            for (int i = 0; i < heightList.size(); i++) {
                if (heightList.get(i).equalsIgnoreCase(poleHeight)) {
                    sp_pole_height_11.setSelection(i, false);
                    break;
                }
            }
        }


    }

    private List<String> getPoleTypeList() {

        List<String> baseTypes = Arrays.asList(
                "PSCC",
                "SPUN",
                "TOWER",
                "RS JOIST"
        );

        List<String> extraTypes = Arrays.asList(
                "RAIL",
                "TUBULAR POLE"
        );

        List<String> result = new ArrayList<>();
        result.add("Select");

        String location =
                sp_is_location_exists.getSelectedItem().toString();

        // Base types always available
        result.addAll(baseTypes);

        // Extra types only for Existing
        if ("Existing".equalsIgnoreCase(location)) {
            result.addAll(extraTypes);
        }

        return result;
    }


