    private String normalizePoleConfig11KV(String config) {

        if (config == null) return "";

        String value = config.trim().toUpperCase();

        // ---- DTR ----
        if (value.equals("DTR POLE")
                || value.equals("DTR-POLE")) {
            return "DTR POLE";
        }

        // ---- HT SERVICE / HTTVR ----
        if (value.equals("HT SERVICE-POLE")
                || value.equals("HT SERVICE POLE")
                || value.equals("HTTVR POLE")
                || value.equals("HT TVR POLE")) {
            return "HTTVR METER POLE";
        }

        // ---- LINE POLE ----
        if (value.equals("LINE POLE")
                || value.equals("LINE-POLE")) {
            return "LINE-POLE";
        }

        // ---- AB POLE ----
        if (value.equals("AB POLE")
                || value.equals("AB-POLE")) {
            return "AB-POLE";
        }

        // ---- UG MARKER ----
        if (value.equals("UG CABLE ROUTE MARKER")
                || value.equals("CABLE ROUTE MARKER")) {
            return "UG CABLE ROUTE MARKER";
        }

        return value;
    }

