    private void repeatPoleLT() {

        Executors.newSingleThreadExecutor().execute(() -> {

            List<NewModel> list =
                    databaseEstimates.getNewSurveyData(EST_NO, "LT", false, GIS_ID);

            if (list == null || list.isEmpty()) return;

            NewModel model = list.get(list.size() - 1);

            runOnUiThread(() -> bindPoleLT(model));
        });
    }

    private void bindPoleLT(NewModel m) {

        String LINE_TYPE = safeString(m.getLINE_TYPE()).toUpperCase();
        String POLE_TYPE = safeString(m.getPOLE_TYPE()).toUpperCase();
        String POLE_HEIGHT = safeString(m.getPOLE_HEIGHT()).toUpperCase();
        String POLE_SUPPORT = safeString(m.getPOLE_SUPPORT()).toUpperCase();
        String PIN_CUT = normalizePinCutLT(m.getPIN_CUT());
        String POLE_CONCRETE = safeString(m.getPOLE_CONCRETE()).toUpperCase();
        String POLE_STRUCTURE = safeString(m.getPOLE_STRUCTURE()).toUpperCase();

        // LINE TYPE
        setSpinner(sp_lineType_lt, LINE_TYPE.equals("OVERHEAD") ? 0 : 1);

        // POLE TYPE
        setupPoleTypeSpinnerLT(POLE_TYPE, POLE_HEIGHT);

        // HEIGHT
        //setupHeightSpinnerLT(POLE_TYPE, POLE_HEIGHT);

        // SUPPORT
        setSpinner(sp_pole_support_lt, POLE_SUPPORT.equals("NONE") ? 1 : 0);

        // PIN / CUT
        setSpinner(sp_pole_pin_cut_point_lt,
                PIN_CUT.equals("PINPOINT") ? 1 :
                        PIN_CUT.equals("CUTPOINT") ? 2 : 0);

        // CONCRETE
        setSpinner(sp_pole_concrete_lt,
                POLE_CONCRETE.equals("YES") ? 2 :
                        POLE_CONCRETE.equals("NO") ? 1 : 0);

        // STRUCTURE
        setSpinner(sp_pole_structure_lt,
                POLE_STRUCTURE.equals("SINGLE-POLE") ? 1 :
                        POLE_STRUCTURE.equals("DOUBLE-POLE") ? 2 :
                                POLE_STRUCTURE.equals("FOUR-POLE") ? 3 : 0);
    }


    private void setupPoleTypeSpinnerLT(String poleType, String poleHeight) {

        List<String> base = Arrays.asList("PSCC", "SPUN", "TOWER", "RS JOIST");
        List<String> extra = Arrays.asList("RAIL", "TUBULAR POLE");

        List<String> list = new ArrayList<>();
        list.add("Select");

        boolean isExisting =
                sp_is_location_exists.getSelectedItem()
                        .toString().equalsIgnoreCase("Existing");

        String selectedType =
                poleType == null ? "" : poleType.trim().toUpperCase();

        // add selected first (repeatPole)
        if (!selectedType.isEmpty()
                && (base.contains(selectedType) || extra.contains(selectedType))) {
            list.add(selectedType);
        }

        for (String s : base) {
            if (!s.equalsIgnoreCase(selectedType)) list.add(s);
        }

        if (isExisting) {
            for (String s : extra) {
                if (!s.equalsIgnoreCase(selectedType)) list.add(s);
            }
        }

        SpinnerAdapter<String> adapter11KV = new SpinnerAdapter<>(context, list);
        // STEP 1: clear listener + set adapter
        sp_pole_type_lt.setOnItemSelectedListener(null);
        sp_pole_type_lt.setAdapter(adapter11KV);
        // STEP 2: restore repeatPole
        if (!selectedType.isEmpty()) {
            int pos = list.indexOf(selectedType);
            if (pos >= 0) {
                sp_pole_type_lt.post(() -> {

                    // restore pole type
                    sp_pole_type_lt.setSelection(pos, false);

                    // restore height AFTER pole type
                    setupHeightSpinnerLT(selectedType, poleHeight);

                    // STEP 3: attach listener AFTER restore
                    attachPoleTypeListenerLT(list);
                });
                return;
            }
        }

        // Normal flow (no repeatPole)
        attachPoleTypeListenerLT(list);
    }

    private void attachPoleTypeListenerLT(List<String> list) {

        sp_pole_type_lt.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> parent, View view, int position, long id) {

                if (position < 0 || position >= list.size()) return;

                String selectedPoleType = list.get(position);

                // USER change → rebuild height
                setupHeightSpinnerLT(selectedPoleType, null);
            }

            @Override
            public void onNothingSelected(AdapterView<?> parent) {
            }
        });
    }

    private void setupHeightSpinnerLT(String poleType, String poleHeight) {
        String pole_type = poleType;

        List<String> heights = new ArrayList<>();
        heights.add("Select");

        if (poleType == null) poleType = "";

        switch (poleType) {
            case "PSCC":
                heights.addAll(Arrays.asList("8", "9.1", "11"));
                break;

            case "SPUN":
            case "RAIL":
                heights.addAll(Arrays.asList("9.5", "11", "12.5"));
                break;

            case "RS JOIST":
            case "TUBULAR POLE":
                heights.addAll(Arrays.asList("9.1", "11"));
                break;

            case "TOWER":
                heights.addAll(Arrays.asList("M+3", "M+6", "M+9", "M+12", "R+"));
                break;
        }

        SpinnerAdapter<String> adapter =
                new SpinnerAdapter<>(
                        this,
                        heights
                );

        sp_pole_height_lt.setOnItemSelectedListener(null);
        sp_pole_height_lt.setAdapter(adapter);

        // restore height during repeatPole
        if (poleHeight != null && !poleHeight.isEmpty()) {
            int pos = heights.indexOf(poleHeight);
            if (pos >= 0) {
                sp_pole_height_lt.setSelection(pos, false);
            }
        }
    }


    private String normalizePinCutLT(String value) {

        if (value == null) return "";

        value = value.trim().toUpperCase();

        if (value.equals("PIN POINT") || value.equals("PINPOINT"))
            return "PINPOINT";

        if (value.equals("CUT POINT") || value.equals("CUTPOINT"))
            return "CUTPOINT";

        return value;
    }


    private String safeString(String value) {
        return value != null ? value.trim() : "";
    }


    private void setDTRPhaseAdapterExisting(String voltage_level) {
        dtr_phase.clear();

        if (voltage_level.equalsIgnoreCase("11KV")) {
            dtr_phase.add("Select");
            dtr_phase.add("I");
            dtr_phase.add("III");
        } else {
            dtr_phase.add("Select");
            dtr_phase.add("I");
        }

        ArrayAdapter<String> adapter = new ArrayAdapter<>(context, R.layout.spinner_items_list, dtr_phase);
        existing_dtr_sp_dtr_phase_11.setAdapter(adapter);
        existing_dtr_sp_dtr_phase_11.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener() {
            @Override
            public void onItemSelected(AdapterView<?> parent, View view, int position, long id) {
                String selectedPhase = parent.getSelectedItem().toString();
                setDTRPhaseAdapter(sp_voltage_level.getSelectedItem().toString());
                sp_dtr_apartment_11.setSelection(0, true);
                sp_dtr_apartment_11_existing.setSelection(0, true);
                if ("I".equalsIgnoreCase(selectedPhase)) {
                    existing_dtr_layout_dtr_capacity.setVisibility(View.VISIBLE);
                    existing_dtr_sp_dtr_capacity_phase1_11.setVisibility(View.VISIBLE);
                    existing_dtr_sp_dtr_capacity_phase2_11.setVisibility(View.GONE);
                    existing_dtr_sp_dtr_capacity_phase1_11.setSelection(0, true);
                    tv_dtr_phase.setText("I");
                } else if ("III".equalsIgnoreCase(selectedPhase)) {
                    existing_dtr_layout_dtr_capacity.setVisibility(View.VISIBLE);
                    existing_dtr_sp_dtr_capacity_phase2_11.setVisibility(View.VISIBLE);
                    existing_dtr_sp_dtr_capacity_phase1_11.setVisibility(View.GONE);
                    existing_dtr_sp_dtr_capacity_phase2_11.setSelection(0, true);
                    tv_dtr_phase.setText("III");
                } else {
                    existing_dtr_layout_dtr_capacity.setVisibility(View.GONE);
                    existing_dtr_sp_dtr_capacity_phase1_11.setVisibility(View.GONE);
                    existing_dtr_sp_dtr_capacity_phase2_11.setVisibility(View.GONE);


                }
            }

            @Override
            public void onNothingSelected(AdapterView<?> parent) {

            }
        });
    }

