    private void addMaterialDataToDataBase11(String TYPE) {
        if (sp_pole_configuration_11.getSelectedItem().toString().equalsIgnoreCase("DTR Pole")
                && !sp_dtr_survey_11.getSelectedItem().toString().equalsIgnoreCase("Existing")) {
            Object selectedItem = sp_dtr_material_11.getSelectedItem();
            if (selectedItem != null) {
                addSpecialMaterial(
                        TYPE,
                        conductorSAPCode11KVDTR,
                        selectedItem.toString(),
                        "1"
                );
            } else {
                openAlertDialogForDTR();
                return;
            }
            // Proposed
            if (sp_dtr_survey_11.getSelectedItem().toString().equalsIgnoreCase("Proposed")
                    || sp_dtr_survey_11.getSelectedItem().toString().equalsIgnoreCase("Enhancement") || sp_dtr_survey_11.getSelectedItem().toString().equalsIgnoreCase("RDSS")) {
                if (sp_dtr_apartment_11.getSelectedItem().toString().equalsIgnoreCase("No")
                        && sp_lt_circuit_available_11.getSelectedItem().toString().equalsIgnoreCase("Yes")) {

                    insertDTRMeterMaterialListToDB(materialListDtrMeter, TYPE);
                }
            }

            // Enhancement
//            if (sp_dtr_survey_11.getSelectedItem().toString().equalsIgnoreCase("Enhancement")) {
//                if (sp_dtr_apartment_11_existing.getSelectedItem().toString().equalsIgnoreCase("No")
//                        && sp_meter_available_11_existing.getSelectedItem().toString().equalsIgnoreCase("Yes")) {
//
//                    insertDTRMeterMaterialListToDB(materialListDtrMeter, TYPE);
//                }
//            }
//            if (sp_dtr_material_11.getSelectedItem().toString()!=null){
//                addSpecialMaterial(TYPE, conductorSAPCode11KVDTR, sp_dtr_material_11.getSelectedItem().toString(), "1");
//            }else {
//                Toast.makeText(context, "HAHAHA", Toast.LENGTH_SHORT).show();
//            }


            // System.out.println("Inserted DTR Pole Material");
        } else if (sp_pole_configuration_11.getSelectedItem().toString().equalsIgnoreCase("DTR Pole")
                && sp_dtr_survey_11.getSelectedItem().toString().equalsIgnoreCase("Existing")) {
            if (sp_dtr_apartment_11_existing.getSelectedItem().toString().equalsIgnoreCase("No")
                    && sp_meter_available_11_existing.getSelectedItem().toString().equalsIgnoreCase("Yes")) {

                insertDTRMeterMaterialListToDB(materialListDtrMeter, TYPE);
            }

        } else if (sp_pole_configuration_11.getSelectedItem().toString().equalsIgnoreCase("HTTVR Meter Pole")) {
            addSpecialMaterial(TYPE, conductorSAPCode11KVDTR, sp_material_httvr.getSelectedItem().toString(), "1");
            insertABMaterialListToDB(materialABList, TYPE);
            //System.out.println("Inserted HTTVR Material");
        } else if (sp_pole_configuration_11.getSelectedItem().toString().equalsIgnoreCase("Line AB-Pole")
                || sp_pole_configuration_11.getSelectedItem().toString().equalsIgnoreCase("AB-Pole")) {
            insertABMaterialListToDB(materialABList, TYPE);
        }


        for (int i = 0; i < materialList11.size(); i++) {
            String qty = materialList11.get(i).getQTY();
            if (qty == null || qty.trim().isEmpty()) {
                qty = "0"; // default if empty
            }


            if (Integer.parseInt(qty) <= 0) {
                continue;
            }

            MaterialPostingModel model = buildCommonModel(TYPE);
            model.setSAP_CODE(materialList11.get(i).getMATERIAL_CODE());
            model.setMATERIAL_DESC(materialList11.get(i).getMATERIAL_DESC());
            model.setCOUNT(materialList11.get(i).getQTY());
            model.setSURVEY_CODE(materialList11.get(i).getSURVEY_CODE());
            model.setDATA_ID(materialList11.get(i).getDATA_ID());
            model.setVOLTAGE_LEVEL("11KV");
            model.setUOM(materialList11.get(i).getUOM());


            boolean status = databaseEstimates.addMaterialData(model);
            if (status) {
                // System.out.println("Inserted Normal Material: " + model.getMATERIAL_DESC() + " Qty=" + qty);
            }
        }
        insertMaterialListToDB(materialList11Pole, TYPE);

        MaterialPostingModel conductorModel = buildCommonModel(TYPE);
        conductorModel.setVOLTAGE_LEVEL("11KV");
        conductorModel.setSAP_CODE(conductorSAPCode11KV);
        conductorModel.setMATERIAL_DESC(list11.isEmpty() ? "" : sp_conductor_size_11.getSelectedItem().toString());
        conductorModel.setCOUNT("0"); // conductor is usually quantityless, set "0"

        databaseEstimates.addMaterialData(conductorModel);
        // System.out.println("Inserted Conductor: " + conductorModel.getMATERIAL_DESC());


        addPoleToDataBase11();
    }

