    private void insertMaterialListToDB(List<MaterialModelPole> list, String TYPE) {
        for (MaterialModelPole item : list) {
            String qty = item.getQTY();
            if (qty == null || qty.trim().isEmpty()) {
                qty = "0";
            }

            if (Integer.parseInt(qty) <= 0) continue;
            MaterialPostingModel model = buildCommonModel(TYPE);
            model.setSAP_CODE(item.getMATERIAL_CODE());
            model.setMATERIAL_DESC(item.getMATERIAL_DESC());
            model.setCOUNT(item.getQTY());
            model.setSURVEY_CODE(item.getSURVEY_CODE());
            model.setDATA_ID(item.getDATA_ID());


            boolean status = databaseEstimates.addMaterialData(model);
            if (status) {
                //  System.out.println("Inserted Material: " + model.getMATERIAL_DESC() + " Qty=" + qty);
            }
        }
    }


    private void insertABMaterialListEdit(List<MaterialModel> materialList, String TYPE) {
        for (int i = 0; i < materialList.size(); i++) {
            MaterialModel current = materialList.get(i);   // edited values
            MaterialModel original = tempListAB11.get(i);   // snapshot (old values)

            int oldQty = 0;
            int newQty = 0;

            try {
                oldQty = Integer.parseInt(
                        original.getQTY() == null || original.getQTY().trim().isEmpty() ? "0" : original.getQTY()
                );
                newQty = Integer.parseInt(
                        current.getQTY() == null || current.getQTY().trim().isEmpty() ? "0" : current.getQTY()
                );
            } catch (NumberFormatException e) {
                continue; // skip invalid qty
            }

            // Skip if both unchanged and zero
            if (oldQty == newQty && newQty == 0) continue;

            MaterialPostingModel model = buildCommonModel(TYPE);
            model.setSAP_CODE(current.getMATERIAL_CODE());
            model.setMATERIAL_DESC(current.getMATERIAL_DESC());
            model.setCOUNT(String.valueOf(newQty));
            model.setSURVEY_CODE(current.getSURVEY_CODE());
            model.setDATA_ID(current.getDATA_ID());

            // ===== MOD_TYPE logic =====
            if (oldQty == 0 && newQty > 0) {
                model.setMOD_TYPE("NEW");
            } else if (oldQty != newQty) {
                model.setMOD_TYPE("EDIT");
                model.setREF_ID(current.getId());   // link to existing record
                model.setUSER_ID(user_id);          // track who edited
            } else {
                continue; // skip unchanged
            }

            boolean status = databaseEstimates.addMaterialData(model);
            if (status) {
//                System.out.println("Inserted/Updated Material: "
//                        + model.getMATERIAL_DESC()
//                        + " OldQty=" + oldQty
//                        + " NewQty=" + newQty
//                        + " MOD_TYPE=" + model.getMOD_TYPE());
            }
        }
    }


