    private void insertPoleMaterialListEdit(List<MaterialModelPole> materialModelPoles, String TYPE) {
        for (int i = 0; i < materialModelPoles.size(); i++) {
            MaterialModelPole current = materialModelPoles.get(i);   // edited via adapter
            MaterialModelPole original = tempListPole.get(i);        // snapshot (old values)

            int oldQty = 0;
            int newQty = 0;
            try {
                oldQty = Integer.parseInt(original.getQTY());
                newQty = Integer.parseInt(current.getQTY());
            } catch (NumberFormatException e) {
                continue; // skip invalid qty
            }

            // skip unchanged & zero entries
            if (oldQty == newQty && newQty == 0) continue;

            MaterialPostingModel model = new MaterialPostingModel();
            model.setESTIMATE_NO(EST_NO);
            model.setVOLTAGE_LEVEL("33KV");
            model.setGIS_ID(GIS_ID);

            if (sp_survey_pole_type.getSelectedItem().toString().equalsIgnoreCase("Mapped Location")) {
                ArrayList<NewModel> latAndLonPole = databaseEstimates.getLatAndLon(
                        EST_NO,
                        sp_exsting_connecting_point.getSelectedItem().toString(),
                        GIS_ID
                );
                model.setLOCATION_ID(latAndLonPole.get(0).getLOCATION_ID());
            } else {
                model.setLOCATION_ID(DATA_MODEL.getLOCATION_ID());
            }

            if (EstimatesMap.IS_INTERMEDIATE_POLE) {
                model.setLOCATION_NO(DATA_MODEL.getPOLE_NO());
            } else {
                model.setLOCATION_NO(DATA_MODEL.getPOLE_NO());
            }

            model.setMATERIAL("");
            model.setSAP_CODE(current.getMATERIAL_CODE());
            model.setMATERIAL_DESC(current.getMATERIAL_DESC());
            model.setCOUNT(String.valueOf(newQty));
            model.setSURVEY_CODE(current.getSURVEY_CODE());
            model.setDATA_ID(current.getDATA_ID());
            model.setTYPE(TYPE);
            if ("WO_RDSS".equalsIgnoreCase(LoginActivity.SURVEY_FROM)) {
                model.setAPP_VERSION(MobileConstants.WO_RDSS_VERSION);
            } else {
                model.setAPP_VERSION(MobileConstants.APP_VERSION);
            }
            model.setAPP_VERSION2(getResources().getString(R.string.displayVersion));

            // ===== MOD_TYPE logic =====
            if (oldQty == 0 && newQty > 0) {
                model.setMOD_TYPE("NEW");
            } else if (oldQty != newQty) {
                model.setMOD_TYPE("EDIT");
                model.setREF_ID(current.getId());   // optional: link to existing record
                model.setUSER_ID(user_id);          // capture editor
            } else {
                continue; // skip unchanged
            }

            databaseEstimates.addMaterialData(model);
        }

    }


