    private void spinnerExistingConnection() {
        if (sp_exsting_connecting_point.getSelectedItem() != null) {
            if (!sp_exsting_connecting_point.getSelectedItem().toString().equalsIgnoreCase("Select")) {
                existingselectedItem = sp_exsting_connecting_point.getSelectedItem().toString();


                if (sp_survey_pole_type.getSelectedItem().toString().equalsIgnoreCase("Mapped Location")) {
                    String location_no = sp_exsting_connecting_point.getSelectedItem().toString().trim();

                    if (BTN_VALUE.equalsIgnoreCase("LT")) {
                        //System.out.println("SELECTED_LT_CKT_LT: TRUE");
                        //System.out.println("SELECTED_LT_CKT: " + WorkInvolmentsActivity.SELECTED_LT_CKT);

                        int ltCount = 0;
                        int kv11Count = 0;
                        int kv33Count = 0;

                        List<String> selectedCktPoleNos = new ArrayList<>();

                        // Step 1: Collect POLE_NO from listLT where circuit matches SELECTED_LT_CKT
                        for (NewModel item : listLT) {
                            if (item.getLT_AVAILABLE().equalsIgnoreCase(WorkInvolmentsActivity.SELECTED_LT_CKT)) {
                                selectedCktPoleNos.add(item.getPOLE_NO());
                            }
                        }

                        // Step 2: Check if current location_no exists in the selected circuit
                        if (selectedCktPoleNos.contains(location_no)) {
                            // Step 3: Count in LT
                            for (NewModel item : listLT) {
                                if (item.getPOLE_NO().equalsIgnoreCase(location_no)) {
                                    ltCount++;
                                    //System.out.println("Matched in LT POLE_NO: " + item.getPOLE_NO());
                                }
                            }

                            // Step 4: Count in 11KV
                            for (NewModel item : list11) {
                                if (item.getPOLE_NO().equalsIgnoreCase(location_no)) {
                                    kv11Count++;
                                    //System.out.println("Matched in 11KV POLE_NO: " + item.getPOLE_NO());
                                }
                            }

                            // Step 5: Count in 33KV
                            for (NewModel item : list33) {
                                if (item.getPOLE_NO().equalsIgnoreCase(location_no)) {
                                    kv33Count++;
                                    //System.out.println("Matched in 33KV POLE_NO: " + item.getPOLE_NO());
                                }
                            }

                            // Step 6: Show alert if conditions match
                            if (
                                    ltCount > 1 ||
                                            (ltCount > 0 && kv11Count > 0) ||
                                            (ltCount > 0 && kv33Count > 0)
                            ) {
                                //System.out.println("POLE_NO '" + location_no + "' found in multiple LT records or across voltage levels (11KV/33KV).");

                                openAlertDialogForMultipleTapping(WorkInvolmentsActivity.SELECTED_LT_CKT, "");
                            }
                        }
                    } else if (BTN_VALUE.equalsIgnoreCase("11KV")) {
                        String feederId = getFeederId(WorkInvolmentsActivity.CLICKED_FEEDER);
                        int kv11Count = 0;
                        int kv33Count = 0;
                        int ltCount = 0;

                        // Step 1: Filter POLE_NO list from selected 11KV feeder
                        List<String> selectedFeederPoleNos = new ArrayList<>();
                        for (NewModel item : list11) {
                            if (item.getFEEDER_ID().equalsIgnoreCase(feederId)) {
                                selectedFeederPoleNos.add(item.getPOLE_NO());
                            }
                        }

                        // Step 2: Proceed only if location_no is part of selected feeder
                        if (selectedFeederPoleNos.contains(location_no)) {

                            // Count in 11KV
                            for (NewModel item : list11) {
                                if (item.getPOLE_NO().equalsIgnoreCase(location_no)) {
                                    kv11Count++;
                                    //System.out.println("Matched in 11KV POLE_NO: " + item.getPOLE_NO());
                                }
                            }

                            // Count in 33KV
                            for (NewModel item : list33) {
                                if (item.getPOLE_NO().equalsIgnoreCase(location_no)) {
                                    kv33Count++;
                                    //System.out.println("Matched in 33KV POLE_NO: " + item.getPOLE_NO());
                                }
                            }

                            // Count in LT
                            for (NewModel item : listLT) {
                                if (item.getPOLE_NO().equalsIgnoreCase(location_no)) {
                                    ltCount++;
                                    //System.out.println("Matched in LT POLE_NO: " + item.getPOLE_NO());
                                }
                            }

                            // Show alert if pole is found in multiple records or across voltage levels
                            if (
                                    kv11Count > 1 ||
                                            (kv11Count > 0 && kv33Count > 0) ||
                                            (kv11Count > 0 && ltCount > 0)
                            ) {
                                //System.out.println("POLE_NO '" + location_no + "' found in multiple 11KV records or across voltage levels (33KV/LT).");
                                String feederName = gettingFeederName();

                                openAlertDialogForMultipleTapping(feederId, feederName);
                            }
                        }
                    } else if (BTN_VALUE.equalsIgnoreCase("33KV")) {
                        String feederId = getFeederId(WorkInvolmentsActivity.CLICKED_FEEDER);
                        int locationCount = 0;

                        for (int i = 0; i < list33.size(); i++) {
                            String modelPoleNo = list33.get(i).getPOLE_NO();

                            if (modelPoleNo.equalsIgnoreCase(location_no)) {
                                locationCount++;
                                //System.out.println("Matched POLE_NO: " + modelPoleNo);
                            }

                            if (locationCount > 1) {
                                //System.out.println("POLE_NO '" + location_no + "' found more than once.");
                                String feederName = gettingFeederName();
                                openAlertDialogForMultipleTapping(feederId, feederName);
                                break;
                            }
                        }
                    }
                }

                if (sp_voltage_level.getSelectedItem().toString().equalsIgnoreCase("LT")) {
                    layout_sp_pole_type_lt.setVisibility(View.VISIBLE);
                    layout_sp_pole_support_lt.setVisibility(View.VISIBLE);
                    layout_sp_pole_height_lt.setVisibility(View.VISIBLE);
                    layout_pole_structure_lt.setVisibility(View.VISIBLE);
                    layout_pole_concrete_lt.setVisibility(View.VISIBLE);


                    if (sp_exsting_connecting_point != null && sp_exsting_connecting_point.getSelectedItem() != null) {
                        ArrayList<NewModel> latAndLonPole = databaseEstimates.getLatAndLon(EST_NO, sp_exsting_connecting_point.getSelectedItem().toString(), GIS_ID);

                        NewModel dtrPole = null;
                        for (NewModel item : list11) {
                            if ("DTR Pole".equalsIgnoreCase(item.getPOLE_CONFIG()) &&
                                    item.getDTR_STRUCTURE_CODE().equals(WorkInvolmentsActivity.SELECTED_DTR)) {
                                dtrPole = item;
                                break;
                            }
                        }

                        if (dtrPole != null) {
                            double dtrLat = Double.parseDouble(dtrPole.getLATITUDE());
                            double dtrLon = Double.parseDouble(dtrPole.getLONGITUDE());
                            double poleLAT = Double.parseDouble(latAndLonPole.get(0).getLATITUDE());
                            double poleLON = Double.parseDouble(latAndLonPole.get(0).getLONGITUDE());


                            double distanceMeters = getDistanceBetweenPoles(dtrLon, dtrLat, poleLON, poleLAT);
                            int distanceInMeters = (int) distanceMeters;
                            last_pole_distance.setText("" + distanceInMeters);
                            // System.out.println("DISTANCE_SETTED_HERE===" + distanceMeters);
                            //Log.d("DISTANCE_CHECK-12", "Distance from DTR Pole: " + distance + " meters" + "DTR_LAT" + " " + dtrLat + " " + "DTR_LONG" + " " + dtrLon);


                        } else {
                            // Log.d("DISTANCE_CHECK", "No DTR Pole found in list.");
                        }
                    }


                    getPoleDataInMappedLocationLT();


                }
                //24-12-24 chandu changes
                if (sp_voltage_level.getSelectedItem().toString().equalsIgnoreCase("11KV")) {
                    //19-12-24 Chandra sekhar Changes
                    if (sp_is_location_exists.getSelectedItem().toString().equalsIgnoreCase("Existing") ||
                            sp_is_location_exists.getSelectedItem().toString().equalsIgnoreCase("Proposed")) {
                        getPoleDataInMappedLocation();

                    }
                } else if (sp_voltage_level.getSelectedItem().toString().equalsIgnoreCase("33KV")) {
                    if (sp_is_location_exists.getSelectedItem().toString().equalsIgnoreCase("Existing") ||
                            sp_is_location_exists.getSelectedItem().toString().equalsIgnoreCase("Proposed")) {
                        getPoleDataInMappedLocation33Kv();

                    }

                }

//                    //19-12-24 Chandra sekhar Changes
//                    if (sp_is_location_exists.getSelectedItem().toString().equalsIgnoreCase("Existing") ||
//                            sp_is_location_exists.getSelectedItem().toString().equalsIgnoreCase("Proposed")) {
//                        getPoleDataInMappedLocation();
//                    }
                if (existingselectedItem.isEmpty()) {
                    if (allList.isEmpty()) {
                        poleNumber = 1;
                    } else {
                        int lastPoleNumber = Integer.parseInt(allList.get(allList.size() - 1).getPOLE_NO());

                        poleNumber = lastPoleNumber;

                        for (int i = 0; i < allList.size(); i++) {
                            int currentPoleNumber = Integer.parseInt(allList.get(i).getPOLE_NO());
                            if (currentPoleNumber > poleNumber) {
                                poleNumber = currentPoleNumber;
                            }
                        }

                        poleNumber++;
                    }

                    location_no.setText("" + poleNumber);

                    if (IS_EDIT) {
                        poleNumber = Integer.parseInt(DATA_MODEL.getPOLE_NO());
                        location_no.setText("" + poleNumber);
                    } else {
                        location_no.setText("" + poleNumber);
                    }

                } else {

                    if (IS_EDIT) {
                        poleNumber = Integer.parseInt(DATA_MODEL.getPOLE_NO());
                        location_no.setText("" + poleNumber);
                    } else {
                        poleNumber = Integer.parseInt(existingselectedItem);
                        location_no.setText("" + poleNumber);
                    }

                    ArrayList<NewModel> latAndLon = databaseEstimates.getLatAndLon(EST_NO, sp_exsting_connecting_point.getSelectedItem().toString(), GIS_ID);
                    ArrayList<NewModel> getData = databaseEstimates.getPoleDetails(EST_NO, sp_exsting_connecting_point.getSelectedItem().toString(), GIS_ID);
                    lattitude = latAndLon.get(0).getLATITUDE();
                    longitude = latAndLon.get(0).getLONGITUDE();
                    lineType = getData.get(0).getLINE_TYPE();
                    poleType = getData.get(0).getPOLE_TYPE();
                    isMultiCir = getData.get(0).getIS_MULTI_CKT();
                    poleHeiht = getData.get(0).getPOLE_HEIGHT();
                    poleSupport = getData.get(0).getPOLE_SUPPORT();
                    countOfSTRUT = getData.get(0).getNo_OF_STRUT();
                    countOfSTRUT = getData.get(0).getNo_OF_STAY();


                }
            } else {

            }
        } else {
            if (allList.isEmpty()) {
                poleNumber = 1;
            } else {
                int lastPoleNumber = Integer.parseInt(allList.get(allList.size() - 1).getPOLE_NO());

                poleNumber = lastPoleNumber;

                for (int i = 0; i < allList.size(); i++) {
                    int currentPoleNumber = Integer.parseInt(allList.get(i).getPOLE_NO());
                    if (currentPoleNumber > poleNumber) {
                        poleNumber = currentPoleNumber;
                    }
                }

                poleNumber++;
            }

            if (IS_EDIT) {
                poleNumber = Integer.parseInt(DATA_MODEL.getPOLE_NO());
                location_no.setText("" + poleNumber);
            } else {
                location_no.setText("" + poleNumber);
            }
        }
    }

