                        material_rv_dtr_meter.setLayoutManager(layoutManagerMeter);
                        material_rv_dtr_meter.setFocusable(false);
                        DTRMeterMaterialAdapter adapterMeter = new DTRMeterMaterialAdapter(materialListDtrMeter, LocationDetails.this, IS_EDIT);
                        material_rv_dtr_meter.setAdapter(adapterMeter);
