    private void setPoleTypeAdapter() {
        poleTypeSurvey.clear();

        if (IS_EDIT) {
            poleTypeSurvey.add("New Location");
        } else {
            boolean isLTButton = BTN_VALUE.equalsIgnoreCase("LT");
            boolean is33KV = sp_voltage_level.getSelectedItem().toString().equalsIgnoreCase("33KV");
            boolean addSelectAndAlert = false;

            if (is33KVSelected && !is11KVSelected && isLTSelected && isLTButton && listLT.isEmpty()) {
                addSelectAndAlert = true;
            } else if (!is33KVSelected && is11KVSelected && isLTSelected && isLTButton) {
                if (!IS_LINE_EXTENSION_LT_DATA_AVAILABLE) {
                    int LOCATIONS_LT = 0;
                    for (int i = 0; i < listLT.size(); i++) {
                        if (listLT.get(i).getLT_AVAILABLE().equalsIgnoreCase(WorkInvolmentsActivity.SELECTED_LT_CKT)) {
                            LOCATIONS_LT++;
                        }
                    }

                    if (LOCATIONS_LT == 0 && sp_is_location_exists.getSelectedItem().toString().equalsIgnoreCase("Proposed")) {
                        addSelectAndAlert = true;

                    }
                }
            }

            if (addSelectAndAlert) {
                poleTypeSurvey.clear();
                poleTypeSurvey.add(EstimatesMap.SELECTED_LOCATION_TYPE);
                //  poleTypeSurvey.add("Select");
                //poleTypeSurvey.add("New Location");
                //poleTypeSurvey.add("Mapped Location");
                showAlertForMulticircuitLT("Pay Attention", "If it is Multi circuit Select New/Mapped Location as Mapped Location");

            } else {
                poleTypeSurvey.clear();
                //poleTypeSurvey.add("New Location");
                poleTypeSurvey.add(EstimatesMap.SELECTED_LOCATION_TYPE);

                if (!is33KV && (!allList.isEmpty() || isLTButton)) {
                    poleTypeSurvey.clear();
                    poleTypeSurvey.add(EstimatesMap.SELECTED_LOCATION_TYPE);
                    // poleTypeSurvey.add("Mapped Location");
                }
            }
        }

        SpinnerAdapter adapter =
                new SpinnerAdapter(context, poleTypeSurvey);

        sp_survey_pole_type.setAdapter(adapter);
//        ArrayAdapter<String> adapter = new ArrayAdapter<>(context, R.layout.spinner_items_list, poleTypeSurvey);
//        sp_survey_pole_type.setAdapter(adapter);


    }


