    private void setPoleSurveyTypeData11KV(String voltageLevel) {
        lineSurveyTypeData.clear();
        if (voltageLevel.equalsIgnoreCase("11KV") || voltageLevel.equalsIgnoreCase("6.3KV")) {

            if (LoginActivity.SURVEY_FROM.equalsIgnoreCase("SOLAR_DPR")) {
                lineSurveyTypeData.clear();
                lineSurveyTypeData.add("Proposed");
            } else {
                if (IS_INTERMEDIATE_POLE) {
                    lineSurveyTypeData.add("Existing");
                } else {
                    if (IS_CURRENT_LOCATION_LINE_EXTENSION_11 || IS_LINE_EXTENSION_11_DATA_AVAILABLE) {
                        if (EstimatesMap.IS_SAME_EXISTING_FEEDER) {
                            lineSurveyTypeData.add("Proposed");
                        } else {
                            lineSurveyTypeData.add("Select");
                            lineSurveyTypeData.add("Proposed");
                            lineSurveyTypeData.add("Existing");
                            lineSurveyTypeData.add("6.3kV to 11kV Conversion");
                        }
                    } else {
                        lineSurveyTypeData.add("Proposed");
                        if ("WO_RDSS".equalsIgnoreCase(LoginActivity.SURVEY_FROM)) {
                            lineSurveyTypeData.add("6.3kV to 11kV Conversion");
                        }
                        //lineSurveyTypeData.add("6.3kV to 11kV Conversion");
                    }
                }

            }


        } else if (voltageLevel.equalsIgnoreCase("33KV")) {

            if (IS_INTERMEDIATE_POLE) {
                lineSurveyTypeData.add("Existing");
            } else {
                if (IS_CURRENT_LOCATION_LINE_EXTENSION_33 || IS_LINE_EXTENSION_33_DATA_AVAILABLE) {
                    if (EstimatesMap.IS_SAME_EXISTING_FEEDER) {
                        lineSurveyTypeData.add("Proposed");
                    } else {
                        lineSurveyTypeData.add("Select");
                        lineSurveyTypeData.add("Proposed");
                        lineSurveyTypeData.add("Existing");
                    }
                } else {
                    lineSurveyTypeData.add("Proposed");

                }
            }


//            if (EstimatesMap.IS_SAME_EXISTING_FEEDER) {
//                lineSurveyTypeData.add("Proposed");
//            } else {
//                lineSurveyTypeData.add("Select");
//                lineSurveyTypeData.add("Proposed");
//                lineSurveyTypeData.add("Existing");
//            }
        } else if (voltageLevel.equalsIgnoreCase("LT")) {
            if (LoginActivity.SURVEY_FROM.equalsIgnoreCase("SOLAR_DPR")) {
                lineSurveyTypeData.clear();
                lineSurveyTypeData.add("Proposed");
            } else {
                if (IS_INTERMEDIATE_POLE) {
                    lineSurveyTypeData.add("Existing");
                } else {
                }
                lineSurveyTypeData.add("Select");
                lineSurveyTypeData.add("Proposed");
                lineSurveyTypeData.add("Existing");

            }

        } else if (IS_CURRENT_LOCATION_LINE_EXTENSION_LT || IS_LINE_EXTENSION_LT_DATA_AVAILABLE) {
        }

        SpinnerAdapter adapterLineSurvey =
                new SpinnerAdapter(context, lineSurveyTypeData);

        sp_line_survey_type.setAdapter(adapterLineSurvey);

    }

