    private void connectivityClick() {
        String location = sp_connecting_point.getSelectedItem().toString();
        // System.out.println("DISTANCE BETWEEN location : " + location);
        if (location != null) {

            //03-01-2025 Chandu Changes
            if (location.equalsIgnoreCase("0")) {
                last_pole_distance.setText("0");
                distance = 0;
                //  System.out.println("SELECTED LOCATION IN :" + location);
            } else {
                ArrayList<NewModel> latAndLon = databaseEstimates.getLatAndLon(EST_NO, sp_connecting_point.getSelectedItem().toString(), GIS_ID);
                for (int i = 0; i < latAndLon.size(); i++) {
                    conPoleLattitude = Double.parseDouble(latAndLon.get(i).getLONGITUDE());
                    conPoleLongitude = Double.parseDouble(latAndLon.get(i).getLATITUDE());
                }
                Location connectingPoleLocation = new Location("ConnectingPole");
                connectingPoleLocation.setLatitude(conPoleLattitude);
                connectingPoleLocation.setLongitude(conPoleLongitude);

                if (allList.size() > 0) {
                    Location currentPoleLocation = new Location("CurrentPole");
                    //LOCATIONS EDIT
                    if (IS_EDIT) {
                        currentPoleLocation.setLatitude(Double.parseDouble(DATA_MODEL.getLONGITUDE()));
                        currentPoleLocation.setLongitude(Double.parseDouble(DATA_MODEL.getLATITUDE()));
                    } else {
                        currentPoleLocation.setLatitude(Double.parseDouble(poleLon));
                        currentPoleLocation.setLongitude(Double.parseDouble(poleLat));
                    }
                    distance = currentPoleLocation.distanceTo(connectingPoleLocation);
                    //    Log.d("currentPoleLocation-->", "onItemSelected: " + connectingPoleLocation + " " + currentPoleLocation);

                    int dis = (int) Math.round(distance);
                    last_pole_distance.setText("" + dis);
                } else {
                    //   Log.d("Distance", "No last pole available to calculate distance.");
                }


                // Log.d("Distance", "Distance between connecting point and last pole: " + distance + " meters");
            }


        }
    }

    private void setFbcScAdapterBasedOnRdssType() {
        Executors.newSingleThreadExecutor().execute(() -> {
            System.out.println("TARGETED_FEE DERS_DB::::: " + RDSS_TYPE);
            List<String> fbcScList = new ArrayList<>();

            if (RDSS_TYPE == null || RDSS_TYPE.trim().isEmpty()) {
                fbcScList.add("Select");

            } else if (RDSS_TYPE.equalsIgnoreCase("BIF")) {
                fbcScList.add("BIFURCATION");

            } else if (RDSS_TYPE.equalsIgnoreCase("AGL")) {
                fbcScList.add("SEGREGATION");

            } else if (RDSS_TYPE.equalsIgnoreCase("AGL_BIF")) {
                fbcScList.add("Select");
                fbcScList.add("BIFURCATION");
                fbcScList.add("SEGREGATION");
            } else {
                fbcScList.add("Select");
            }
            runOnUiThread(() -> {

                ArrayAdapter<String> adapter = new ArrayAdapter<>(
                        LocationDetails.this,
                        android.R.layout.simple_spinner_item,
                        fbcScList
                );
                adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);

                sp_fbc_sc.setAdapter(adapter);

            });

        });
    }

    private void setTargetFeedersAdapter() {
        Executors.newSingleThreadExecutor().execute(() -> {
            System.out.println("TARGET_FEEDERS_11KV:::" + FEEDERS);
            List<String> feeders_11kv = new ArrayList<>();
            feeders_11kv.add("Select");

            if (FEEDERS != null && !FEEDERS.isEmpty()) {
                String[] items = FEEDERS.split(",");

                for (String item : items) {
                    int start = item.lastIndexOf("(");
                    int end = item.lastIndexOf(")");

                    if (start != -1 && end != -1) {
                        String name = item.substring(0, start).trim();
                        String code = item.substring(start + 1, end).trim();

                        // Add to list
                        feeders_11kv.add(name + "~" + code);
                    }
                }
            }

            runOnUiThread(() -> {
                if (BTN_VALUE.equalsIgnoreCase("11KV")) {
                    ArrayAdapter<String> adapter = new ArrayAdapter<>(
                            LocationDetails.this,
                            android.R.layout.simple_spinner_item,
                            feeders_11kv
                    );
                    adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
                    sp_target_feeders_11kv.setAdapter(adapter);
                } else {
                    ArrayAdapter<String> adapter = new ArrayAdapter<>(
                            LocationDetails.this,
                            android.R.layout.simple_spinner_item,
                            feeders_11kv
                    );
                    adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
                    sp_target_feeders_lt.setAdapter(adapter);
                }
            });

        });
    }


    public void getAddress(Context context, double latitude, double longitude, AddressCallback callback) {

        try {

            Log.d("ADDRESS LAT ", "" + latitude);
            Log.d("ADDRESS LON ", "" + longitude);
            Geocoder geocoder = new Geocoder(context, Locale.getDefault());

            List<Address> addresses = geocoder.getFromLocation(latitude, longitude, 2);

            List<AddressModel> result = new ArrayList<>();
            if (addresses != null) {
                AddressModel model = new AddressModel();
                model.setAddress_1(addresses.get(0).getAddressLine(0));
                model.setAddress_2(addresses.get(1).getAddressLine(0));
                model.setLocality(addresses.get(0).getLocality());
                model.setSub_locality(addresses.get(0).getSubLocality());
                model.setState(addresses.get(0).getAdminArea());
                model.setBlock(addresses.get(0).getFeatureName() == null ? addresses.get(0).getPremises() : addresses.get(0).getFeatureName());
                result.add(model);
            }

            callback.onSuccess(result);

        } catch (Exception e) {
            callback.onError(e.getMessage());
        }
    }

    private File cameraImageFile;

    private void openCamera() {

        if (ContextCompat.checkSelfPermission(
                this,
                Manifest.permission.CAMERA)
                != PackageManager.PERMISSION_GRANTED) {

            ActivityCompat.requestPermissions(
                    this,
                    new String[]{Manifest.permission.CAMERA},
                    CAMERA_PERMISSION_CODE);

            return;
        }

        try {

            cameraImageFile = new File(
                    getCacheDir(),
                    "camera_" + System.currentTimeMillis() + ".jpg"
            );

            imageUri = FileProvider.getUriForFile(
                    this,
                    "com.apepdcl.gis_survey.fileprovider",
                    cameraImageFile
            );

            cameraLauncher.launch(imageUri);

        } catch (Exception e) {

            e.printStackTrace();

            Toast.makeText(
                    this,
                    "Unable to open camera",
                    Toast.LENGTH_SHORT
            ).show();
        }
    }

